// th16_s6_b5 — TH16 v1.00a Stage 6 最终Boss 第3非符
// 源: st06bs.ecl.txt Boss3 (296-359) + Boss3_at (361-414)
// 入口承接 Boss 总初始化: 位置(0,128)、受击/体碰框、该段自己的 moveLimit 与等待。

const TIME_LIMIT: int = 2524;   // 120 外壳缓冲 + 2400 源中断窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;
const SOURCE_WINDOW: int = 2400; // 0335 setInterrupt(0, 2500, 2400, "BossCard3") 的计时窗口
const BOSS_HP: int = 17500;      // 0299 lifeSet(17500)

// 0366 etSprite(0, 9, 14): TH16 type 9 = 苦无，有效色 0-15
const TH16_KUNAI: int = 496;
const KUNAI_COLOR: int = 14;

// 0379/0389/0390: 出生ANIM投1帧退位移由 L0000_ANIM_RETREAT 并入sh_dist；
// 两条 ACCELWEIRD(0x200000) 各60帧，标量速 0.5 -> 3.0/4.0 -> 2.0，方向保留。
const ANIM_RETREAT: fx = 2fx;      // 4 * 初速0.5，方向沿弹角反向
const SPAWN_DIST: fx = 24fx;       // 0391 etDist(0, 24.0f)
const NET_SPAWN_DIST: fx = 22fx;   // 24 - 2

xformdef SPEED_RAMP(top: fx) {
    @60 step_speed(top, 60);
    step_speed(2fx, 60);
}

// 0412 moveLimit(0, 128, 240, 32): 完整宽高 -> 位置 x∈[-120,120]、y∈[112,144]；
// 0412 moveRand 的方向内区为宽高1/4 -> x±60、y[120,136]。
sub arm_next_step() {
    var total: int = self_int(1);
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    if k <= total {
        var spd: fx = self_fx(2) * (total - k) / total;
        var nx: fx = $self_x + self_fx(0) * spd;
        var ny: fx = $self_y + self_fx(1) * spd;
        if nx < -120fx { nx = -120fx; }
        if nx > 120fx { nx = 120fx; }
        if ny < 112fx { ny = 112fx; }
        if ny > 144fx { ny = 144fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
    } else {
        move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    }
}

// 0412 moveRand(frames, mode, speed)：调用时取一次方向，速度按线性从 speed 降到 0。
// mode 不覆盖速度插值槽（沿用线性）；方向取样与竖直修正按移动专题配方。
sub move_rand_begin(frames: int, speed: fx) {
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 120fx {
        if a < 0 { a = -a; }
    } else if $self_y > 136fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // ±pi/2 护栏，0.05rad ~ 522BAM
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_fx(2, speed);
    set_self_int(0, 0);
    set_self_int(1, frames);
    arm_next_step();
}

// 每帧按源"移动->ECL"顺序预排下一步位移；int2 为入场以来的帧计数（源计时窗口）。
sub wait_n(frames: int) {
    for i in 0..frames {
        if self_int(2) >= SOURCE_WINDOW { return; }
        wait(1);
        set_self_int(2, self_int(2) + 1);
        arm_next_step();
    }
}

// 0361 Boss3_at：每波整周环，基角每波加 3.883222rad 并每波减 0.008727rad。
sub boss3_at() {
    var n: int = 11;
    var top: fx = 4fx;
    var gap: int = 2;
    if global(GVAR_RANK) == RANK_EASY {
        n = 6;
        top = 3fx;
        gap = 4;
    }
    sh_reset(0);                    // 0364 etNew(0)
    sh_sprite(0, TH16_KUNAI, KUNAI_COLOR); // 0366
    sh_ring(0, 1);                  // 0365 etAim(0, 3) 固定方向整周环
    sh_aim(0, 0);
    sh_count(0, n, 1);              // 0368-0376 路数随难度，1层
    sh_speed(0, 0.5fx, 0fx);        // 0378 etSpeed(0, 0.5f, 0.2f)，单层取首速
    sh_dist(0, NET_SPAWN_DIST);     // 0391 + 0379 出生退位移
    sh_xform(0, SPEED_RAMP(top));   // 0389/0390 两段60帧变速

    var base: angle = 0deg;         // 0392 %A = 0.0f
    var step: angle = 40503 as angle; // 0393 %B = 3.883222f
    for i in 0..241 {               // 0394 $C = 241
        if self_int(2) >= SOURCE_WINDOW { return; }
        sh_angle(0, base, 0deg);    // 0397 etAngle(0, %A, 0.0f)
        sh_fire(0);                 // 0398 etOn(0)
        base = base + step;         // 0399 %A = %A + %B
        step = step - (91 as angle); // 0400 %B = %B - 0.008727f
        wait_n(gap);                // 0401-0410 难度等待4/2帧
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(28fx);              // Boss 入口 0029 setHurtbox(56,56)
    set_hitbox(25fx);               // Boss 入口 0030 setHitbox(50,50)
    set_self_int(2, 0);
    wait_n(180);                    // 0340/0343/0346 三段60帧入场等待
    while self_int(2) < SOURCE_WINDOW {
        move_rand_begin(240, 0.5fx); // 0352 moveRand(240, 9, 0.5f)
        boss3_at();                  // 0353 @Boss3_at()
        if self_int(2) < SOURCE_WINDOW {
            move_rand_begin(60, 1.9fx); // 0354 moveRand(60, 4, 1.9f)
            wait_n(60);              // 0355 wait(60)
        }
    }
    // 源在此超时跳入 BossCard3；单卡外壳按自然退场结束。
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, BOSS_HP, 0, 0, 1, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
